create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_DIM_WAWI_ITEM_VARIANT_1 (
	WAWI_ITEM_VARIANT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) of the Wawi item_1 variant.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
	WAWI_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) of the Wawi item_1 on which the variant is based.',
	COUNTRY_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the country_1 organization which has created the Wawi item_1 variant. (This column is denormalized from t_wawi_item.)',
	COUNTRY_ORG_CD VARCHAR(2) NOT NULL COMMENT 'The code of the business country_1 for which created this Wawi item. (The business country_1 is not identical to a political country.)',
	WAWI_ITEM_VARIANT_NR NUMBER(38,0) NOT NULL COMMENT 'The number which identifies the Wawi item_1 variant within the given country_1 organization. Note that the number is unique for a certain point in time, but may be re_1-used later on. It is also known as the long Wawi number.',
	WAWI_ITEM_VARIANT_NAME VARCHAR(100) NOT NULL COMMENT 'The name by which the Wawi item_1 variant is known within the given country_1 organization.',
	WAWI_ITEM_VARIANT_DESCR VARCHAR(250) COMMENT 'A more detailed (free text) description for the Wawi item_1 variant - which applies to the given country_1 organization.',
	WAWI_ITEM_VARIANT_CREATION_DT DATE NOT NULL COMMENT 'The date when the item_1 variant was created in the operational system (Wawi) of the given country_1 organization.',
	WAWI_COUNTRY_STATUS_ID NUMBER(38,0) NOT NULL COMMENT 'The identifier for the country_1-level lifecycle status_1 for Wawi item_1 variants. (HQ status_1)',
	WAWI_COUNTRY_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the country_1-level lifecycle status_1 for Wawi item_1 variants. (Description in group language, i.e. in German)',
	WAWI_WH_STATUS_ID NUMBER(38,0) NOT NULL COMMENT 'The identifier for the warehouse-level lifecycle status_1 for Wawi item_1 variants.',
	WAWI_WH_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the warehouse-level lifecycle status_1 for Wawi item_1 variants. (Description in group language, i.e. in German)',
	CASE_SIZE_CNT NUMBER(38,0) NOT NULL COMMENT 'The number of individual items that are contained in the Wawi item_1 variant. (Note that the individual item_1 represents the smallest sellable unit. E.g. if a packed try of meat contains two slices, the entire tray is considered one sellable unit.) In case of weight-based items this is the integer part of the expected net weight of the package.',
	WEIGHT_BASED_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the Wawi item_1 variant is sold by weight instead of count.',
	ITEM_FAM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the item_1 family to which this product belongs.',
	ITEM_FAM_NR VARCHAR(100) COMMENT 'The number by which the related item_1 family is known to business.',
	ITEM_FAM_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the item_1 family. (Name in group language, i.e. in German)',
	SUB_ITEM_GRP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for a sub item_1 group to which this product belongs.',
	SUB_ITEM_GRP_NR VARCHAR(100) COMMENT 'The number by which the related sub item_1 group is known to business.',
	SUB_ITEM_GRP_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the sub item_1 group. (Name in group language, i.e. in German)',
	FOOD_FG BOOLEAN NOT NULL COMMENT 'An indicator distinguishing food from non-food items.',
	INT_ITEM_GRP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier [surrogate key] for an international item_1 group to which this product belongs',
	INT_ITEM_GRP_NR VARCHAR(100) COMMENT 'The number by which the related international item_1 group is known to business.',
	INT_ITEM_GRP_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the international item_1 group. (Name in group language, i.e. in German)',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_WAWI_ITEM_VARIANT primary key (WAWI_ITEM_VARIANT_SID, DWH_VALID_FROM_TMSP)
)COMMENT='A Wawi item_1 can exist in various sizes, e.g. a box consisting of 10 individual items and another box consisting of 15 items. The Wawi item_1 variant describes the package_1 in which individual sales_1 units are contained. The Wawi item_1 variant is similar, but not identical to the (global) logistic variant, as Wawi items are specific to a country_1 organization and as Wawi sometimes creates multiple items for the same global product. E.g. Wawi creates a new item_1 if the composition of a package_1 changes or if an item_1 has a different sales_1 price.'
;